const data = $input.item.json;
const current = data.current;
const hourly = data.hourly;

// Truncate minutes from current time (e.g., 06:15 -> 06:00) to match hourly array
const currentTime = current.time;
const currentHourString = currentTime.substring(0, 14) + "00"; 
const currentIndex = hourly.time.indexOf(currentHourString);

if (currentIndex < 24) throw new Error("Not enough historical data for lags");

const temp_lag_1 = hourly.temperature_2m[currentIndex - 1];
const temp_lag_3 = hourly.temperature_2m[currentIndex - 3];
const temp_lag_24 = hourly.temperature_2m[currentIndex - 24];
const humidity_lag_1 = hourly.relative_humidity_2m[currentIndex - 1];
const rain_lag_1 = hourly.precipitation[currentIndex - 1];

const temp_rolling_6 = hourly.temperature_2m.slice(currentIndex - 6, currentIndex).reduce((a,b)=>a+b,0)/6;
const temp_rolling_24 = hourly.temperature_2m.slice(currentIndex - 24, currentIndex).reduce((a,b)=>a+b,0)/24;

const date = new Date(currentTime);

return {
  hour: date.getHours(),
  month: date.getMonth() + 1,
  temperature_2m: current.temperature_2m,
  relative_humidity_2m: current.relative_humidity_2m,
  precipitation: current.precipitation,
  wind_speed_10m: current.wind_speed_10m,
  surface_pressure: current.surface_pressure,
  cloud_cover: current.cloud_cover,
  temp_lag_1: Number(temp_lag_1.toFixed(2)),
  temp_lag_3: Number(temp_lag_3.toFixed(2)),
  temp_lag_24: Number(temp_lag_24.toFixed(2)),
  humidity_lag_1: Number(humidity_lag_1.toFixed(2)),
  rain_lag_1: Number(rain_lag_1.toFixed(2)),
  temp_rolling_6: Number(temp_rolling_6.toFixed(2)),
  temp_rolling_24: Number(temp_rolling_24.toFixed(2))
};

